import torch


def run_correctness(inp):
    output = torch.special.scaled_modified_bessel_k1(inp.float())
    return output.to(inp.dtype)


def run(inp):
    return torch.special.scaled_modified_bessel_k1(inp)


def generate_inputs(ctx, device):
    shape = tuple(ctx["inp__shape"])
    dtype = getattr(torch, ctx["inp__dtype"])
    inp = torch.rand(shape, dtype=dtype, device=device) + 0.1
    return {"inp": inp}
